import { after } from 'next/server';
import { logPageView } from '@/lib/analytics';

export default function Home() {
  // Schedule analytics logging to run AFTER the response is sent
  // This uses Next.js's after() API which ensures the work doesn't block the response
  after(async () => {
    await logPageView('/');
  });

  return (
    <main>
      <h1>Welcome to Our Site!</h1>
      <p>This page logs views without blocking the response using Next.js's after() API.</p>
    </main>
  );
}

